CREATE OR REPLACE FUNCTION public.save_study_week(p_week date,p_summary text,p_insights jsonb,p_sessions jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); pid uuid; item jsonb; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('study:'||uid::text,0)); INSERT INTO public.study_plans(user_id,week_start,summary,insights) VALUES(uid,p_week,p_summary,p_insights) ON CONFLICT(user_id,week_start) DO UPDATE SET summary=excluded.summary,insights=excluded.insights,generated_at=now() RETURNING id INTO pid; DELETE FROM public.study_sessions WHERE user_id=uid AND plan_id=pid AND status='planejada'; FOR item IN SELECT * FROM jsonb_array_elements(p_sessions) LOOP INSERT INTO public.study_sessions(user_id,plan_id,topic_id,date,start_minutes,duration,type,format) VALUES(uid,pid,item->>'topic_id',(item->>'date')::date,(item->>'start_minutes')::integer,(item->>'duration')::integer,item->>'type',item->>'format'); END LOOP; RETURN pid; END $$; REVOKE EXECUTE ON FUNCTION public.save_study_week(date,text,jsonb,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_study_week(date,text,jsonb,jsonb) TO authenticated,service_role;